package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		// Allow all origins for WebSocket connections
		return true
	},
}

type Command struct {
	Action string `json:"action"`
	Target string `json:"target"`
	Payload string `json:"payload"`
}

type AuditEntry struct {
	User    string `json:"user"`
	Action  string `json:"action"`
	Details string `json:"details"`
}

var (
	auditLog  []AuditEntry
	auditLock sync.Mutex
	auditFile = "/var/log/app/audit.jsonl"
)

func writeAuditToDisk(entry AuditEntry) error {
	f, err := os.OpenFile(auditFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	defer f.Close()
	data, _ := json.Marshal(entry)
	_, err = f.Write(append(data, '\n'))
	return err
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	// Session cookie is sent automatically by browser on WS upgrade
	sessionCookie, err := r.Cookie("session_id")
	if err != nil || sessionCookie.Value == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// No CSRF token validation on WebSocket handshake
	// Origin header is not checked (CheckOrigin returns true)
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	user := validateSession(sessionCookie.Value)
	if user == "" {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid session"}`))
		return
	}

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var cmd Command
		if err := json.Unmarshal(message, &cmd); err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid json"}`))
			continue
		}

		// Process privileged actions via WebSocket
		result := processCommand(user, cmd)
		conn.WriteMessage(websocket.TextMessage, []byte(result))
	}
}

func processCommand(user string, cmd Command) string {
	auditLock.Lock()
	entry := AuditEntry{User: user, Action: cmd.Action, Details: fmt.Sprintf("%s -> %s", cmd.Target, cmd.Payload)}
	auditLog = append(auditLog, entry)
	// Persist audit trail to disk for compliance
	if err := writeAuditToDisk(entry); err != nil {
		log.Printf("WARN: audit write failed: %v", err)
	}
	auditLock.Unlock()

	switch cmd.Action {
	case "transfer_funds":
		return fmt.Sprintf(`{"status":"ok","msg":"transferred %s to %s"}`, cmd.Payload, cmd.Target)
	case "update_email":
		return fmt.Sprintf(`{"status":"ok","msg":"email updated to %s"}`, cmd.Payload)
	case "delete_account":
		return fmt.Sprintf(`{"status":"ok","msg":"account %s scheduled for deletion"}`, cmd.Target)
	default:
		return `{"error":"unknown action"}`
	}
}

func validateSession(sessionID string) string {
	// Simplified session validation - in production would check Redis/DB
	if len(sessionID) == 32 {
		return "authenticated_user"
	}
	return ""
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})
	log.Println("WebSocket service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
